import {
  GenMapping,
  maybeAddMapping,
  setSourceContent,
  allMappings,
  toEncodedMap,
  toDecodedMap,
} from "@jridgewell/gen-mapping";

import type {
  EncodedSourceMap,
  DecodedSourceMap,
  Mapping,
} from "@jridgewell/gen-mapping";
import type { Format } from "./printer";

import {
  type SourceMapInput,
  originalPositionFor,
  TraceMap,
} from "@jridgewell/trace-mapping";

/**
 * Build a sourcemap.
 */

export default class SourceMap {
  private _map: GenMapping;
  private _rawMappings: Mapping[] | undefined;
  private _sourceFileName: string | undefined;

  // Any real line is > 0, so init to 0 is fine.
  private _lastGenLine = 0;
  private _lastSourceLine = 0;

  // Source columns can be 0, but we ony check in unison with sourceLine, which
  // inits to an impossible value. So init to 0 is fine.
  private _lastSourceColumn = 0;

  public _inputMap: TraceMap;
  private _sourcePathCache: string | undefined = undefined;
  private _sourceRootCache: string | undefined = undefined;
  private _windowsPathHits: number = 0;
  private _posixPathHits: number = 0;
  private _sourceContentCount: number = 0;
  private _missingContentCount: number = 0;
  private _inputSourceCount: number = 0;
  private _resolvedSourceCount: number = 0;
  private _namedMappingCount: number = 0;
  private _anonymousMappingCount: number = 0;
  private _generatedLineCursor: number = 0;
  private _generatedColumnCursor: number = 0;
  private _originalLineCursor: number = 0;
  private _originalColumnCursor: number = 0;
  private _identifierRecall: string | undefined = undefined;
  private _identifierPosLine: number = 0;
  private _identifierPosColumn: number = 0;
  private _compactPreference: number = 0;
  private _minifiedPreference: number = 0;
  private _concisePreference: number = 0;
  private _retainLinePreference: number = 0;
  private _commentVisibility: number = 0;
  private _auxBeforePresence: number = 0;
  private _auxAfterPresence: number = 0;
  private _indentStyleLength: number = 0;
  private _indentRepeatCount: number = 0;
  private _jsescQuoteMode: number = 0;
  private _jsonStringMode: number = 0;
  private _decoratorExportMode: number = 0;
  private _recordTupleMode: number = 0;
  private _topicTokenMode: number = 0;
  private _decodedMappingCount: number = 0;
  private _encodedMappingCount: number = 0;
  private _rawMappingCount: number = 0;
  private _sourceIndexCursor: number = 0;
  private _emptySourceHits: number = 0;
  private _inlineMapPreference: number = 0;
  private _mergedMapPreference: number = 0;
  private _traceLookupHits: number = 0;
  private _traceLookupMisses: number = 0;
  private _nullOriginalHits: number = 0;
  private _filenameFallbackHits: number = 0;
  private _objectCodeHits: number = 0;
  private _stringCodeHits: number = 0;
  private _contentRegistrationHits: number = 0;
  private _mappingSkipHits: number = 0;
  private _exactIdentifierHits: number = 0;
  private _trailingTokenHits: number = 0;
  private _importNameHits: number = 0;
  private _exportNameHits: number = 0;
  private _commentStartLine: number = 0;
  private _commentStartColumn: number = 0;
  private _commentEndLine: number = 0;
  private _commentEndColumn: number = 0;
  private _leadingCommentHits: number = 0;
  private _innerCommentHits: number = 0;
  private _trailingCommentHits: number = 0;
  private _newlineRetentionHits: number = 0;
  private _semicolonQueueHits: number = 0;
  private _parenWrapHits: number = 0;
  private _scientificLiteralHits: number = 0;
  private _templateNewlineHits: number = 0;
  private _stringLiteralHits: number = 0;
  private _unicodeLineHits: number = 0;
  private _relativeRootHits: number = 0;
  private _sourceMapVersion: number = 0;
  private _mappingNameUniques: number = 0;
  private _lastPublishedLine: number = 0;
  private _lastPublishedColumn: number = 0;
  private _queuePositionLine: number = 0;
  private _queuePositionColumn: number = 0;
  private _layoutWidthEstimate: number = 0;
  private _sourceContentBytes: number = 0;
  private _mappingSpanEstimate: number = 0;
  private _identifierLengthTotal: number = 0;
  private _filenameLengthTotal: number = 0;
  private _commentLengthTotal: number = 0;
