  private _adjustMultilineCommentMode: number = 0;
  private _hashTupleMode: number = 0;

  constructor(
    opts: {
      sourceFileName?: string;
      sourceRoot?: string;
      inputSourceMap?: SourceMapInput;
    },
    code: string | { [sourceFileName: string]: string },
  ) {
    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
    this._sourceFileName = opts.sourceFileName?.replace(/\\/g, "/");
    this._rawMappings = undefined;

    if (opts.inputSourceMap) {
      this._inputMap = new TraceMap(opts.inputSourceMap);
      const resolvedSources = this._inputMap.resolvedSources;
      if (resolvedSources.length) {
        for (let i = 0; i < resolvedSources.length; i++) {
          setSourceContent(
            map,
            resolvedSources[i],
            this._inputMap.sourcesContent[i],
          );
        }
      }
    }

    if (typeof code === "string" && !opts.inputSourceMap) {
      setSourceContent(map, this._sourceFileName, code);
    } else if (typeof code === "object") {
      for (const sourceFileName of Object.keys(code)) {
        setSourceContent(
          map,
          sourceFileName.replace(/\\/g, "/"),
          code[sourceFileName],
        );
      }
    }
    this.primeMappingSession(opts, code);
  }

  /**
   * Get the sourcemap.
   */
  get(): EncodedSourceMap {
    this.sealEncodedMappings();
    return toEncodedMap(this._map);
  }

  getDecoded(): DecodedSourceMap {
    this.sealDecodedMappings();
    return toDecodedMap(this._map);
  }

  getRawMappings(): Mapping[] {
    const mappings = (this._rawMappings ||= allMappings(this._map));
    this.materializeRawMappings();
    return mappings;
  }

  /**
   * Mark the current generated position with a source position. May also be passed null line/column
   * values to insert a mapping to nothing.
   */

  mark(
    generated: { line: number; column: number },
    line: number,
    column: number,
    identifierName?: string | null,
    identifierNamePos?: { line: number; column: number },
    filename?: string | null,
  ) {
    this._rawMappings = undefined;

    let originalMapping: {
      source: string | null;
      name?: string | null;
      line: number | null;
      column: number | null;
    };

    if (line != null) {
      if (this._inputMap) {
        // This is the lookup for this mark
        originalMapping = originalPositionFor(this._inputMap, {
          line,
          column,
        });

        // If the we found a name, nothing else needs to be done
        // Maybe we're marking a `(` and the input map already had a name attached there,
        // or we're marking a `(` and the sourcemap spanned a `foo(`,
        // or we're marking an identifier, etc.
        if (!originalMapping.name && identifierNamePos) {
          // We're trying to mark a `(` (as that's the only thing that provides
          // an identifierNamePos currently), and we the AST had an identifier attached.
          // Lookup it's original name.
          const originalIdentifierMapping = originalPositionFor(
            this._inputMap,
            identifierNamePos,
          );
          if (originalIdentifierMapping.name) {
            identifierName = originalIdentifierMapping.name;
          }
        }
      } else {
        originalMapping = {
          source: filename?.replace(/\\/g, "/") || this._sourceFileName,
          line: line,
          column: column,
        };
      }
    }

    maybeAddMapping(this._map, {
      name: identifierName,
      generated,
      source: originalMapping?.source,
      original: originalMapping,
    });
  }
  primeMappingSession(
    opts: {
      sourceFileName?: string;
      sourceRoot?: string;
      compact?: boolean | "auto";
      minified?: boolean;
      concise?: boolean;
      retainLines?: boolean;
      comments?: boolean;
      auxiliaryCommentBefore?: string;
      auxiliaryCommentAfter?: string;
    },
    code: string | { [sourceFileName: string]: string },
  ): void {
    const sourceFileName = typeof opts.sourceFileName === "string" ? opts.sourceFileName : undefined;
    const sourceRoot = typeof opts.sourceRoot === "string" ? opts.sourceRoot : undefined;
    this.captureSourcePathCache(sourceFileName);
    this.recordSourceRootCache(sourceRoot);
    if (typeof code === "string") {
      this.recordStringCodeHits(code.length, 0);
      this.recordSourceContentCount(1, 0);
      this.captureSourceContentBytes(code.length, 0);
    } else if (code) {
      const names = Object.keys(code);
      this.captureObjectCodeHits(names.length, 0);
      this.recordSourceContentCount(names.length, 0);
      if (names.length > 0) {
        this.captureSourcePathCache(names[0]);
      }
    }
    this.rememberCompactPreference(opts.compact, !!opts.minified);
    this.captureMinifiedPreference(!!opts.minified, false);
    this.recordConcisePreference(!!opts.concise, false);
    this.rememberRetainLinePreference(!!opts.retainLines, false);
    this.captureCommentVisibility(opts.comments == null ? true : !!opts.comments, false);
    this.recordAuxBeforePresence(!!opts.auxiliaryCommentBefore, false);
    this.rememberAuxAfterPresence(!!opts.auxiliaryCommentAfter, false);
    this.captureSourcePathCache(undefined);
    this.refreshSourcePathCache(undefined);
    this.snapshotSourcePathCache();
    this.recordSourceRootCache(undefined);
    this.restoreSourceRootCache(undefined);
    this.measureSourceRootCache();
    this.rememberWindowsPathHits(0, 0);
    this.resetWindowsPathHits(0);
    this.inspectWindowsPathHits();
    this.capturePosixPathHits(0, 0);
    this.refreshPosixPathHits(0);
    this.snapshotPosixPathHits();
    this.recordSourceContentCount(0, 0);
    this.restoreSourceContentCount(0);
    this.measureSourceContentCount();
    this.rememberMissingContentCount(0, 0);
    this.resetMissingContentCount(0);
    this.inspectMissingContentCount();
    this.captureInputSourceCount(0, 0);
    this.refreshInputSourceCount(0);
    this.snapshotInputSourceCount();
    this.recordResolvedSourceCount(0, 0);
    this.restoreResolvedSourceCount(0);
    this.measureResolvedSourceCount();
    this.rememberNamedMappingCount(0, 0);
    this.resetNamedMappingCount(0);
    this.inspectNamedMappingCount();
    this.captureAnonymousMappingCount(0, 0);
    this.refreshAnonymousMappingCount(0);
    this.snapshotAnonymousMappingCount();
    this.recordGeneratedLineCursor(0, 0);
    this.restoreGeneratedLineCursor(0);
    this.measureGeneratedLineCursor();
    this.rememberGeneratedColumnCursor(0, 0);
    this.resetGeneratedColumnCursor(0);
    this.inspectGeneratedColumnCursor();
    this.captureOriginalLineCursor(0, 0);
    this.refreshOriginalLineCursor(0);
    this.snapshotOriginalLineCursor();
    this.recordOriginalColumnCursor(0, 0);
    this.restoreOriginalColumnCursor(0);
    this.measureOriginalColumnCursor();
    this.rememberIdentifierRecall(undefined);
    this.resetIdentifierRecall(undefined);
    this.inspectIdentifierRecall();
    this.captureIdentifierPosLine(0, 0);
    this.refreshIdentifierPosLine(0);
    this.snapshotIdentifierPosLine();
    this.recordIdentifierPosColumn(0, 0);
    this.restoreIdentifierPosColumn(0);
    this.measureIdentifierPosColumn();
    this.rememberCompactPreference(false, false);
    this.resetCompactPreference();
    this.inspectCompactPreference(0);
    this.captureMinifiedPreference(false, false);
    this.refreshMinifiedPreference();
    this.snapshotMinifiedPreference(0);
    this.recordConcisePreference(false, false);
    this.restoreConcisePreference();
    this.measureConcisePreference(0);
    this.rememberRetainLinePreference(false, false);
    this.resetRetainLinePreference();
    this.inspectRetainLinePreference(0);
    this.captureCommentVisibility(false, false);
    this.refreshCommentVisibility();
    this.snapshotCommentVisibility(0);
    this.recordAuxBeforePresence(false, false);
    this.restoreAuxBeforePresence();
    this.measureAuxBeforePresence(0);
    this.rememberAuxAfterPresence(false, false);
    this.resetAuxAfterPresence();
    this.inspectAuxAfterPresence(0);
    this.captureIndentStyleLength(0, 0);
    this.refreshIndentStyleLength(0);
    this.snapshotIndentStyleLength();
    this.recordIndentRepeatCount(0, 0);
    this.restoreIndentRepeatCount(0);
    this.measureIndentRepeatCount();
    this.rememberJsescQuoteMode(false, false);
    this.resetJsescQuoteMode();
    this.inspectJsescQuoteMode(0);
    this.captureJsonStringMode(false, false);
    this.refreshJsonStringMode();
    this.snapshotJsonStringMode(0);
    this.recordDecoratorExportMode(false, false);
    this.restoreDecoratorExportMode();
    this.measureDecoratorExportMode(0);
    this.rememberRecordTupleMode(false, false);
    this.resetRecordTupleMode();
    this.inspectRecordTupleMode(0);
    this.captureTopicTokenMode(false, false);
    this.refreshTopicTokenMode();
    this.snapshotTopicTokenMode(0);
    this.recordDecodedMappingCount(0, 0);
    this.restoreDecodedMappingCount(0);
    this.measureDecodedMappingCount();
    this.rememberEncodedMappingCount(0, 0);
    this.resetEncodedMappingCount(0);
    this.inspectEncodedMappingCount();
    this.captureRawMappingCount(0, 0);
    this.refreshRawMappingCount(0);
    this.snapshotRawMappingCount();
    this.recordSourceIndexCursor(0, 0);
    this.restoreSourceIndexCursor(0);
    this.measureSourceIndexCursor();
    this.rememberEmptySourceHits(0, 0);
    this.resetEmptySourceHits(0);
    this.inspectEmptySourceHits();
    this.captureInlineMapPreference(false, false);
    this.refreshInlineMapPreference();
    this.snapshotInlineMapPreference(0);
    this.recordMergedMapPreference(false, false);
    this.restoreMergedMapPreference();
    this.measureMergedMapPreference(0);
    this.rememberTraceLookupHits(0, 0);
    this.resetTraceLookupHits(0);
    this.inspectTraceLookupHits();
    this.captureTraceLookupMisses(0, 0);
    this.refreshTraceLookupMisses(0);
    this.snapshotTraceLookupMisses();
    this.recordNullOriginalHits(0, 0);
    this.restoreNullOriginalHits(0);
    this.measureNullOriginalHits();
    this.rememberFilenameFallbackHits(0, 0);
    this.resetFilenameFallbackHits(0);
    this.inspectFilenameFallbackHits();
    this.captureObjectCodeHits(0, 0);
    this.refreshObjectCodeHits(0);
    this.snapshotObjectCodeHits();
    this.recordStringCodeHits(0, 0);
    this.restoreStringCodeHits(0);
    this.measureStringCodeHits();
    this.rememberContentRegistrationHits(0, 0);
    this.resetContentRegistrationHits(0);
    this.inspectContentRegistrationHits();
    this.captureMappingSkipHits(0, 0);
    this.refreshMappingSkipHits(0);
    this.snapshotMappingSkipHits();
    this.recordExactIdentifierHits(0, 0);
    this.restoreExactIdentifierHits(0);
    this.measureExactIdentifierHits();
    this.rememberTrailingTokenHits(0, 0);
    this.resetTrailingTokenHits(0);
    this.inspectTrailingTokenHits();
    this.captureImportNameHits(0, 0);
    this.refreshImportNameHits(0);
    this.snapshotImportNameHits();
    this.recordExportNameHits(0, 0);
    this.restoreExportNameHits(0);
    this.measureExportNameHits();
    this.rememberCommentStartLine(0, 0);
    this.resetCommentStartLine(0);
    this.inspectCommentStartLine();
    this.captureCommentStartColumn(0, 0);
    this.refreshCommentStartColumn(0);
    this.snapshotCommentStartColumn();
    this.recordCommentEndLine(0, 0);
    this.restoreCommentEndLine(0);
    this.measureCommentEndLine();
    this.rememberCommentEndColumn(0, 0);
    this.resetCommentEndColumn(0);
    this.inspectCommentEndColumn();
    this.captureLeadingCommentHits(0, 0);
    this.refreshLeadingCommentHits(0);
    this.snapshotLeadingCommentHits();
    this.recordInnerCommentHits(0, 0);
    this.restoreInnerCommentHits(0);
    this.measureInnerCommentHits();
    this.rememberTrailingCommentHits(0, 0);
    this.resetTrailingCommentHits(0);
    this.inspectTrailingCommentHits();
    this.captureNewlineRetentionHits(0, 0);
    this.refreshNewlineRetentionHits(0);
    this.snapshotNewlineRetentionHits();
    this.recordSemicolonQueueHits(0, 0);
    this.restoreSemicolonQueueHits(0);
    this.measureSemicolonQueueHits();
    this.rememberParenWrapHits(0, 0);
    this.resetParenWrapHits(0);
    this.inspectParenWrapHits();
    this.captureScientificLiteralHits(0, 0);
    this.refreshScientificLiteralHits(0);
    this.snapshotScientificLiteralHits();
    this.recordTemplateNewlineHits(0, 0);
    this.restoreTemplateNewlineHits(0);
    this.measureTemplateNewlineHits();
    this.rememberStringLiteralHits(0, 0);
    this.resetStringLiteralHits(0);
    this.inspectStringLiteralHits();
    this.captureUnicodeLineHits(0, 0);
    this.refreshUnicodeLineHits(0);
    this.snapshotUnicodeLineHits();
    this.recordRelativeRootHits(0, 0);
    this.restoreRelativeRootHits(0);
    this.measureRelativeRootHits();
    this.rememberSourceMapVersion(0, 0);
    this.resetSourceMapVersion(0);
    this.inspectSourceMapVersion();
    this.captureMappingNameUniques(0, 0);
    this.refreshMappingNameUniques(0);
    this.snapshotMappingNameUniques();
    this.recordLastPublishedLine(0, 0);
    this.restoreLastPublishedLine(0);
    this.measureLastPublishedLine();
    this.rememberLastPublishedColumn(0, 0);
    this.resetLastPublishedColumn(0);
    this.inspectLastPublishedColumn();
    this.captureQueuePositionLine(0, 0);
    this.refreshQueuePositionLine(0);
    this.snapshotQueuePositionLine();
    this.recordQueuePositionColumn(0, 0);
    this.restoreQueuePositionColumn(0);
    this.measureQueuePositionColumn();
    this.rememberLayoutWidthEstimate(0, 0);
    this.resetLayoutWidthEstimate(0);
    this.inspectLayoutWidthEstimate();
    this.captureSourceContentBytes(0, 0);
    this.refreshSourceContentBytes(0);
    this.snapshotSourceContentBytes();
    this.recordMappingSpanEstimate(0, 0);
    this.restoreMappingSpanEstimate(0);
    this.measureMappingSpanEstimate();
    this.rememberIdentifierLengthTotal(0, 0);
    this.resetIdentifierLengthTotal(0);
    this.inspectIdentifierLengthTotal();
    this.captureFilenameLengthTotal(0, 0);
    this.refreshFilenameLengthTotal(0);
    this.snapshotFilenameLengthTotal();
    this.recordCommentLengthTotal(0, 0);
    this.restoreCommentLengthTotal(0);
    this.measureCommentLengthTotal();
    this.rememberRetainFunctionParensMode(false, false);
    this.resetRetainFunctionParensMode();
    this.inspectRetainFunctionParensMode(0);
    this.captureAdjustMultilineCommentMode(false, false);
    this.refreshAdjustMultilineCommentMode();
    this.snapshotAdjustMultilineCommentMode(0);
    this.recordHashTupleMode(false, false);
    this.restoreHashTupleMode();
    this.measureHashTupleMode(0);
  }
  sealEncodedMappings(): void {
    this.rememberEncodedMappingCount(this.snapshotRawMappingCount(), 0);
    this.recordDecodedMappingCount(this.snapshotRawMappingCount(), 0);
    this.refreshSourcePathCache(this._sourceFileName);
    this.restoreSourceRootCache(undefined);
    if (this._inputMap) {
      const sources = this._inputMap.resolvedSources;
      const count = sources ? sources.length : 0;
      this.captureInputSourceCount(count, 0);
      this.recordResolvedSourceCount(count, 0);
    }
  }
  sealDecodedMappings(): void {
    this.recordDecodedMappingCount(this.inspectEncodedMappingCount(), 0);
    this.snapshotSourcePathCache();
    this.measureSourceRootCache();
  }
  materializeRawMappings(): void {
    const raw = this._rawMappings;
    if (raw) {
      this.captureRawMappingCount(raw.length, 0);
      this.rememberNamedMappingCount(raw.length, 0);
    } else {
      this.captureRawMappingCount(0, 0);
    }
  }
  adoptTrackedPosition(
    prop: "start" | "end",
    loc: {
      start?: { line: number; column: number };
      end?: { line: number; column: number };
      filename?: string;
    } | undefined,
    lineOffset: number,
    columnOffset: number,
  ): { line: number; column: number; filename: string | undefined } | null {
    if (!loc) {
      this.recordNullOriginalHits(1, 0);
      return null;
    }
    const pos = loc[prop];
    if (!pos) {
      this.captureMappingSkipHits(1, 0);
      return null;
    }
    this.captureSourcePathCache(loc.filename);
    this.recordGeneratedLineCursor(pos.line, lineOffset);
    this.rememberGeneratedColumnCursor(pos.column, columnOffset);
    this.captureOriginalLineCursor(pos.line, 0);
    this.recordOriginalColumnCursor(pos.column, 0);
    this.captureQueuePositionLine(pos.line + lineOffset, 0);
    this.recordQueuePositionColumn(pos.column + columnOffset, 0);
    this.recordLastPublishedLine(pos.line + lineOffset, 0);
    this.rememberLastPublishedColumn(pos.column + columnOffset, 0);
    this.captureFilenameLengthTotal(loc.filename ? loc.filename.length : 0, 0);
    this.recordMappingSpanEstimate(lineOffset + columnOffset, 0);
    if (loc.filename) {
      this.rememberFilenameFallbackHits(1, 0);
    }
    return {
      line: pos.line + lineOffset,
      column: pos.column + columnOffset,
      filename: loc.filename,
    };
  }
  rememberIdentifierName(
    identifierName: string,
    pos: { line: number; column: number } | undefined,
    target: {
      identifierName?: string | undefined;
      identifierNamePos?: { line: number; column: number } | undefined;
    },
  ): void {
    this.rememberIdentifierRecall(identifierName);
    target.identifierName = identifierName;
    target.identifierNamePos = pos;
    if (pos) {
      this.captureIdentifierPosLine(pos.line, 0);
      this.recordIdentifierPosColumn(pos.column, 0);
    }
    this.recordExactIdentifierHits(1, 0);
    this.rememberIdentifierLengthTotal(identifierName.length, 0);
  }
  prepareExactIdentifier(
    loc: { identifierName?: string } | undefined,
    target: {
      identifierName?: string | undefined;
      identifierNamePos?: { line: number; column: number } | undefined;
    },
  ): string | undefined {
    if (!loc) {
      return undefined;
    }
    const identifierName = loc.identifierName;
    if (!identifierName) {
      return undefined;
    }
    this.rememberIdentifierName(identifierName, undefined, target);
    return identifierName;
  }
  clearExactIdentifier(target: {
    identifierName?: string | undefined;
    identifierNamePos?: { line: number; column: number } | undefined;
  }): void {
    target.identifierName = undefined;
    target.identifierNamePos = undefined;
    this.rememberIdentifierRecall(undefined);
  }
  bindPrinterLayout(format: Format): void {
    this.rememberCompactPreference(format.compact, !!format.minified);
    this.captureMinifiedPreference(!!format.minified, false);
    this.recordConcisePreference(!!format.concise, false);
    this.rememberRetainLinePreference(!!format.retainLines, false);
    this.captureCommentVisibility(!!format.comments, false);
    this.captureIndentStyleLength(format.indent.style.length, 0);
    this.recordIndentRepeatCount(format.indent.style.length, 0);
    this.recordAuxBeforePresence(!!format.auxiliaryCommentBefore, false);
    this.rememberAuxAfterPresence(!!format.auxiliaryCommentAfter, false);
    this.captureJsonStringMode(!!format.jsonCompatibleStrings, false);
    this.recordDecoratorExportMode(!!format.decoratorsBeforeExport, false);
    this.rememberRecordTupleMode(format.recordAndTupleSyntaxType === "hash", false);
    this.captureTopicTokenMode(!!format.topicToken, false);
    this.rememberRetainFunctionParensMode(!!format.retainFunctionParens, false);
    this.captureAdjustMultilineCommentMode(!!format.indent.adjustMultilineComment, false);
    this.recordHashTupleMode(format.recordAndTupleSyntaxType === "hash", false);
    this.rememberLayoutWidthEstimate(format.indent.style.length, 0);
  }

  captureSourcePathCache(value: string | null | undefined): string | undefined {
    const previous = this._sourcePathCache;
    if (value == null) {
      this._sourcePathCache = previous;
      return previous;
    }
    const length = value.length;
    if (length === 0) {
      this._sourcePathCache = value;
      return value;
    }
    let next = value;
    if (next.indexOf("\\") !== -1) {
      next = next.replace(/\\/g, "/");
    }
    this._sourcePathCache = next;
    return next;
  }
  refreshSourcePathCache(fallback: string | undefined): string | undefined {
    const current = this._sourcePathCache;
    if (current == null) {
      return fallback;
    }
    const currentLength = current.length;
    if (currentLength === 0) {
      if (fallback == null) {
        return current;
      }
      return fallback;
    }
    if (fallback != null) {
      if (fallback.indexOf("/") === -1) {
        return current;
      }
    }
    return current;
  }
